const allItems = $input.all();
const first    = allItems[0].json;

// Approved EL v3 behavior tags — keep these, strip everything else in brackets
// (phonetic guides like [POO-mah POON-koo] would be read aloud literally by EL)
const ALLOWED_TAGS = new Set(['[whispers]', '[curious]', '[pause]', '[awe]', '[dramatic tone]']);

function stripPhoneticsKeepTags(text) {
  return text
    .replace(/\[[^\]]+\]/g, (match) => ALLOWED_TAGS.has(match) ? match : '')
    .replace(/  +/g, ' ')   // collapse double-spaces left by stripped brackets
    .trim();
}

