  { Authorization: `Bearer ${GH_TOKEN}`, 'User-Agent': 'ruins-untold-n8n' }
);
if (checkResp.statusCode === 200 && checkResp.body?.sha) {
  sha = checkResp.body.sha;
}

const body = { message: `Add EL script for ${slug}`, content: agg.b64Script };
if (sha) body.sha = sha;

const putResp = await httpsReq('PUT',
  `https://api.github.com/repos/JeezyAndNay/YouTubeAutomation/contents/${ghPath}`,
  { Authorization: `Bearer ${GH_TOKEN}`, 'Content-Type': 'application/json', 'User-Agent': 'ruins-untold-n8n' },
  JSON.stringify(body)
);

if (putResp.statusCode < 200 || putResp.statusCode >= 300) {
  throw new Error(`GitHub push failed ${putResp.statusCode}: ${putResp.rawBody.slice(0,300)}`);
}

const ghSha = putResp.body?.content?.sha ?? null;
console.log(`[GITHUB] Pushed: ${ghPath} SHA=${ghSha?.slice(0,8) ?? 'n/a'}`);
await new Promise(r => setTimeout(r, 3000));
return [{ json: { ...agg, githubSha: ghSha } }];

