const EL_KEY    = $env.ELEVENLABS_API_KEY;
const projectId = $('Create EL Project').item.json.project.project_id;

if (!EL_KEY)    throw new Error('ELEVENLABS_API_KEY not in $env');
if (!projectId) throw new Error('No project_id from Create EL Project (expected .project.project_id)');

const maxAttempts = 25;
const intervalMs  = 45000;

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  await new Promise(r => setTimeout(r, intervalMs));
  const resp = await httpsReq('GET',
    `https://api.elevenlabs.io/v1/studio/projects/${projectId}`,
    { 'xi-api-key': EL_KEY }
  );
  const data    = resp.body;
  const state   = data?.state ?? 'unknown';
  const canDl   = data?.can_be_downloaded ?? false;
  const ch0     = (data?.chapters ?? [])[0];
  const chState = ch0?.state ?? 'unknown';
  console.log(`[POLL ${attempt}/${maxAttempts}] project=${state} chapter=${chState} can_dl=${canDl}`);

  if (canDl === true) {
    return [{ json: { projectId, state, chapterState: chState, attempts: attempt } }];
  }
  if (state === 'error' || state === 'failed') {
    throw new Error(`EL conversion failed (${state}): ${ch0?.last_conversion_error || JSON.stringify(data)}`);
  }
}
throw new Error(`EL conversion timed out after ${maxAttempts} polls (~${Math.round(maxAttempts * intervalMs / 60000)} min)`);

